<template><el-card v-if="hr" style="max-width:520px"><template #header>{{hr.name}} · 个人中心</template><el-descriptions :column="1" border><el-descriptions-item label="用户名">{{hr.username}}</el-descriptions-item><el-descriptions-item label="手机">{{hr.phone}}</el-descriptions-item><el-descriptions-item label="电话">{{hr.telephone}}</el-descriptions-item><el-descriptions-item label="地址">{{hr.address}}</el-descriptions-item></el-descriptions><el-button type="primary" style="margin-top:16px" @click="edit=true">修改资料</el-button><el-button type="danger" @click="password=true">修改密码</el-button><el-dialog v-model="edit" title="修改资料"><el-form :model="form" label-width="80"><el-form-item label="姓名"><el-input v-model="form.name"/></el-form-item><el-form-item label="手机"><el-input v-model="form.phone"/></el-form-item><el-form-item label="电话"><el-input v-model="form.telephone"/></el-form-item><el-form-item label="地址"><el-input v-model="form.address"/></el-form-item></el-form><template #footer><el-button @click="edit=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="password" title="修改密码"><el-form :model="pass" label-width="90"><el-form-item label="旧密码"><el-input v-model="pass.oldpass" type="password"/></el-form-item><el-form-item label="新密码"><el-input v-model="pass.pass" type="password"/></el-form-item></el-form><template #footer><el-button @click="password=false">取消</el-button><el-button type="primary" @click="savePassword">保存</el-button></template></el-dialog></el-card></template>
<script setup>import {onMounted,ref} from 'vue';import {profile,updateProfile,updatePassword} from '@/api/profile.js';const hr=ref(),form=ref({}),edit=ref(false),password=ref(false),pass=ref({});async function load(){hr.value=(await profile()).data;form.value={...hr.value}}async function save(){await updateProfile(form.value);edit.value=false;load()}async function savePassword(){await updatePassword(pass.value);password.value=false;pass.value={}}onMounted(load)</script>
